package cn.fuzhu.toolkit.modules;
import cn.fuzhu.toolkit.FuzhuToolkitPlugin; import cn.fuzhu.toolkit.module.AbstractModule; import org.bukkit.Bukkit; import org.bukkit.command.*; import org.bukkit.entity.Player;
public class PlayerInfoModule extends AbstractModule {public PlayerInfoModule(FuzhuToolkitPlugin p){super(p);config=p.moduleConfig(id());}public String id(){return "PlayerInfo";}public String description(){return "查看玩家位置、血量与延迟";}public boolean handle(CommandSender s,String l,String[] a){Player p=a.length>0?Bukkit.getPlayerExact(a[0]):ModuleUtil.player(plugin,s);if(p==null){plugin.msg(s,"&c玩家不在线。");return true;}plugin.msg(s,"&b玩家 &f"+p.getName()+" &7| 世界: &f"+p.getWorld().getName()+" &7| 坐标: &f"+p.getLocation().getBlockX()+","+p.getLocation().getBlockY()+","+p.getLocation().getBlockZ()+" &7| 血量: &f"+(int)p.getHealth()+" &7| Ping: &f"+p.getPing());return true;}}
